<script setup lang="ts">
import { randomId } from '../../utils/random-id';
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { useUnsavedDraft } from '../../composables/unsaved';
import { RouterLink, useRoute, useRouter } from 'vue-router';
import { runtimeAction, runtimeRequest, watchRun, downloadRuntimeArtifact } from '../../api/typescript';
import { ArtifactUploadResponseSchema, ConfigSnapshotSchema, MessageEventSchema, RunDetailSchema, type AgentDefinition, type ArtifactUploadResponse, type ContentPart, type RunEvent } from '../../../../packages/contracts/src/index';
import { ConversationDetailSchema, ConversationListSchema, ConversationSchema, type Conversation } from '../../../../packages/contracts/src/management';
const emit = defineEmits<{ 'inspect-run': [id: string] }>();
const route = useRoute(); const router = useRouter();
const conversations = ref<Conversation[]>([]); const agents = ref<AgentDefinition[]>([]); const agentId = ref(''); const detail = ref<ReturnType<typeof ConversationDetailSchema.parse>>(); const run = ref<ReturnType<typeof RunDetailSchema.parse>>(); const text = ref(''); const error = ref(''); const busyCount = ref(0); const busy = computed(() => busyCount.value > 0); const uploading = ref(false); const attachments = ref<ArtifactUploadResponse[]>([]); let stream: AbortController | undefined; let selectedVersion = 0; let poll: ReturnType<typeof setInterval> | undefined; let refreshing = false; let initialized = false; let disposed = false;
const draft = useUnsavedDraft('未发送的消息与附件', () => ({ text: text.value, attachments: attachments.value.map(item => item.id) }));
const active = computed(() => !!run.value && ['running','queued','paused'].includes(run.value.run.status));
const preview = computed(() => { let value = ''; for (const event of run.value?.events ?? []) { if (event.type === 'message_delta') value += event.text; if (event.type === 'message_snapshot' || event.type === 'completed') value = event.text; } return value; });
const showPreview = computed(() => run.value && !detail.value?.entries.some(e => e.role === 'assistant' && e.runId === run.value?.run.id));
async function refreshList(): Promise<void> { conversations.value = (await runtimeRequest('conversations', ConversationListSchema)).conversations.filter(c => c.platform === 'dashboard'); }
function onEvent(event: RunEvent): void { if (!run.value || event.runId !== run.value.run.id || run.value.events.some(e => e.sequence === event.sequence)) return; run.value.events.push(event); if (event.type === 'started') run.value.run.status = 'running'; if (event.type === 'paused') run.value.run.status = 'paused'; if (event.type === 'completed' || event.type === 'failed' || event.type === 'cancelled') { run.value.run.status = event.type; void refreshCurrent().catch(e => { error.value = e instanceof Error ? e.message : '刷新失败'; }); } }
function watchRunStream(id: string): void { stream?.abort(); stream = new AbortController(); const signal = stream.signal; void watchRun(id, signal, onEvent).catch(e => { if (!signal.aborted) error.value = e instanceof Error ? e.message : '实时连接中断'; }); }
async function refreshCurrent(): Promise<void> { const id = detail.value?.conversation.id; if (!id || refreshing) return; refreshing = true; try { const data = await runtimeRequest(`conversations/${id}`, ConversationDetailSchema); if (detail.value?.conversation.id === id) detail.value = data; await refreshList(); } finally { refreshing = false; } }
function clearSelection(): void { stream?.abort(); run.value = undefined; detail.value = undefined; text.value = ''; attachments.value = []; draft.markSaved(); }
async function syncSelection(): Promise<void> {
  const version = ++selectedVersion;
  const id = typeof route.query.conversation === 'string' ? route.query.conversation : '';
  clearSelection();
  if (!id || id === 'new') return;
  try {
    const data = await runtimeRequest(`conversations/${encodeURIComponent(id)}`, ConversationDetailSchema);
    if (version !== selectedVersion) return;
    if (data.conversation.platform !== 'dashboard') throw new Error('IM 会话请从对应平台继续，或在会话管理中从历史新建对话');
    detail.value = data; agentId.value = data.conversation.agentId;
    const last = data.runIds.at(-1);
    if (last) {
      const result = await runtimeRequest(`runs/${encodeURIComponent(last)}`, RunDetailSchema);
      if (version !== selectedVersion) return;
      run.value = result; if (active.value) watchRunStream(last);
    }
  } catch (cause) { if (version === selectedVersion) throw cause; }
}
async function select(id: string): Promise<void> { if (busy.value || uploading.value || route.query.conversation === id) return; await router.push({ query: { ...route.query, conversation: id } }); }
async function act(fn: () => Promise<void>): Promise<void> { error.value = ''; busyCount.value++; try { await fn(); } catch(e) { error.value = e instanceof Error ? e.message : '操作失败'; } finally { busyCount.value--; } }
async function create(): Promise<void> {
  if (busy.value || uploading.value || !agentId.value) return;
  const chosenAgent = agentId.value;
  if (route.query.conversation !== 'new') { const failure = await router.push({ query: { ...route.query, conversation: 'new' } }); if (failure) return; }
  const version = selectedVersion;
  await act(async () => {
    const item = await runtimeRequest('conversations', ConversationSchema, { agentId: chosenAgent });
    if (version !== selectedVersion || route.path !== '/chat') return;
    await refreshList();
    if (version !== selectedVersion || route.path !== '/chat') return;
    await router.replace({ query: { ...route.query, conversation: item.id } });
  });
}
async function send(): Promise<void> { if (busy.value || uploading.value || route.query.conversation !== detail.value?.conversation.id || (!text.value.trim() && !attachments.value.length)) return; const version = selectedVersion; await act(async () => { if (!detail.value) throw new Error('请先创建会话'); const conversation = detail.value.conversation; const previous = conversation.lastMessage; if (!previous) throw new Error('此旧会话缺少身份信息，请创建新会话'); const parts: ContentPart[] = [{ type: 'text', text: text.value }, ...attachments.value.map((a): ContentPart => a.mimeType.startsWith('image/') ? { type: 'image', url: a.url, artifactId: a.id, mimeType: a.mimeType } : { type: 'file', url: a.url, artifactId: a.id, mimeType: a.mimeType, name: a.name, size: a.size })]; const message = MessageEventSchema.parse({ ...previous, messageId: randomId(), timestamp: Date.now(), parts }); const result = await runtimeRequest('chat', RunDetailSchema, { conversationId: conversation.id, message }); if (version !== selectedVersion) return; text.value = ''; attachments.value = []; draft.markSaved(); run.value = result; await refreshCurrent(); if (version !== selectedVersion) return; const continuation = conversations.value.find(c => c.platform === conversation.platform && c.sessionId === conversation.sessionId && c.agentId === conversation.agentId && c.generation === result.run.generation); if (continuation && continuation.id !== conversation.id) { await router.replace({ query: { ...route.query, conversation: continuation.id } }); return; } if (active.value) watchRunStream(result.run.id); }); }
async function upload(event: Event): Promise<void> { if (busy.value || uploading.value || !(event.target instanceof HTMLInputElement)) return; const version = selectedVersion; const input = event.target; uploading.value = true; await act(async () => { for (const file of Array.from(input.files ?? [])) { if (file.size > 10 * 1024 * 1024) throw new Error('每个附件最多 10 MiB'); const mimeType = file.type || (file.name.endsWith('.md') ? 'text/markdown' : file.name.endsWith('.txt') ? 'text/plain' : 'application/octet-stream'); if (!['image/jpeg','image/png','image/webp','image/gif','text/plain','text/markdown','application/pdf'].includes(mimeType)) throw new Error('支持图片、文本、Markdown 和 PDF'); const content = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => typeof reader.result === 'string' ? resolve(reader.result.split(',')[1] ?? '') : reject(new Error('读取失败')); reader.onerror = () => reject(new Error('读取失败')); reader.readAsDataURL(file); }); if (version !== selectedVersion) return; const attachment = await runtimeRequest('artifacts', ArtifactUploadResponseSchema, { name: file.name, mimeType, encoding: 'base64', content }); if (version !== selectedVersion) return; attachments.value.push(attachment); } input.value = ''; }); uploading.value = false; }
async function stop(): Promise<void> { await act(async () => { if (run.value) await runtimeAction(`runs/${run.value.run.id}/cancel`, {}); }); }
onMounted(() => { void act(async () => { const config = await runtimeRequest('config', ConfigSnapshotSchema); agents.value = config.config.agents.filter(a => a.enabled); agentId.value = config.config.flow.routing.defaultAgentId; await refreshList(); if (disposed || route.path !== '/chat') return; initialized = true; if (typeof route.query.conversation === 'string') await syncSelection(); else { const first = conversations.value[0]?.id; if (first) await router.replace({ query: { ...route.query, conversation: first } }); } }); poll = setInterval(() => { if (active.value) void refreshCurrent().catch(e => { error.value = e instanceof Error ? e.message : '刷新失败'; }); }, 2000); });
watch(() => route.query.conversation, () => { if (initialized && route.path === '/chat') void act(syncSelection); }, { flush: 'sync' });
onBeforeUnmount(() => { disposed = true; selectedVersion++; stream?.abort(); if (poll) clearInterval(poll); });
</script>
<template><section class="management-workspace"><header><div><h2>{{ detail?.conversation.title ?? 'Web Chat' }}</h2><p>这里仅显示控制台对话。<RouterLink to="/sessions">查看 QQ / NapCat、Telegram、微信等全部平台会话</RouterLink>。发送后立即执行，无需发布配置。</p></div><div class="actions"><select v-model="agentId" :disabled="busy" aria-label="新会话 Agent"><option v-for="agent in agents" :key="agent.id" :value="agent.id">{{ agent.displayName }}</option></select><button :disabled="busy || !agents.length" @click="create">新会话</button></div></header><p v-if="error" role="alert" class="error">{{ error }}</p><div class="chat-columns"><aside class="management-list"><button v-for="item in conversations" :key="item.id" :class="{ selected: detail?.conversation.id === item.id }" :disabled="busy || uploading" @click="select(item.id)"><strong>{{ item.title }}</strong><small>{{ item.agentId }} · {{ new Date(item.updatedAt).toLocaleDateString() }}</small></button><p v-if="!conversations.length && agents.length">选择 Agent，点击“新会话”开始。</p><p v-if="!agents.length && !busy">尚无可用 Agent，请先<RouterLink to="/agents">创建并启用 Agent</RouterLink>。</p></aside><div class="management-editor"><p v-if="busy && !detail" class="empty" role="status">正在载入会话…</p><p v-else-if="!detail && agents.length" class="empty">选择已有会话，或点击右上角“新会话”。</p><div class="transcript" role="log" aria-label="聊天记录"><article v-for="entry in detail?.entries ?? []" :key="entry.id" class="entry" :class="entry.role"><small>{{ entry.role === 'user' ? (entry.senderName || '你') : 'Agent' }}</small><template v-for="(part,index) in entry.parts" :key="index"><p v-if="part.type === 'text'">{{ part.text }}</p><p v-else-if="part.type === 'file'"><button v-if="part.artifactId" @click="act(() => downloadRuntimeArtifact(part.artifactId ?? '', part.name))">下载 {{ part.name }}</button><span v-else>附件：{{ part.name }}</span></p><p v-else-if="part.type === 'image'"><button v-if="part.artifactId" @click="act(() => downloadRuntimeArtifact(part.artifactId ?? '', 'image'))">查看图片</button><span v-else>[图片]</span></p><div v-else-if="part.type === 'quote'" class="quoted-message"><small>引用 {{part.senderName || part.senderId || '未知发送者'}} · {{part.messageId}}</small><p>{{part.text || '原消息无文字'}}</p><p v-if="part.attachments?.length">{{part.attachments.map(item=>item.type==='image'?'[引用图片]':`[引用文件：${item.name}]`).join(' ')}}</p><small v-if="part.availability==='partial'||part.availability==='unavailable'">引用内容不完整或部分附件不可用</small></div><p v-else-if="part.type === 'mention'">@{{ part.name || part.userId }}</p><p v-else-if="part.type === 'reference'">{{ part.label }}</p></template></article><article v-if="showPreview" class="entry assistant"><small>Agent · {{ run?.run.status }}</small><p>{{ preview || (active ? '正在处理…' : run?.run.summary || '本次执行结束。') }}</p></article><p v-if="detail && !detail.entries.length && !active">向 Agent 发送第一条消息。</p></div><div v-if="run" class="actions"><button v-if="active" :disabled="busy" @click="stop">停止</button><button @click="emit('inspect-run', run.run.id)">{{ run.run.status === 'paused' ? '处理工具审批' : '查看执行详情' }}</button></div><form v-if="detail" @submit.prevent="send"><label>消息<textarea v-model="text" rows="3" :required="!attachments.length" :disabled="busy || detail.conversation.archived" placeholder="发送消息，执行过程中也可以补充要求"/></label><p v-if="draft.dirty.value" class="muted" role="status">有未发送的消息或附件。</p><div class="actions"><label>附件<input type="file" multiple accept=".png,.jpg,.jpeg,.webp,.gif,.txt,.md,.pdf" :disabled="busy || uploading || detail.conversation.archived" @change="upload"/></label><button :disabled="busy || uploading || detail.conversation.archived">{{ busy ? '处理中…' : active ? '补充消息' : '发送' }}</button></div><div class="actions"><button v-for="(attachment,index) in attachments" :key="attachment.id" type="button" :disabled="busy || uploading" @click="attachments.splice(index,1)">{{ attachment.name }} ×</button></div><p v-if="detail.conversation.archived">此会话已归档，请先到 <RouterLink :to="{path:'/sessions',query:{conversation:detail.conversation.id}}">会话管理</RouterLink> 取消归档。</p></form></div></div></section></template>
<style scoped src="./management.css"></style>
<style scoped>.chat-columns{display:grid;grid-template-columns:220px minmax(0,1fr);gap:20px}.chat-columns .management-editor{min-height:500px}.transcript{min-height:260px;align-content:start}.management-editor form{display:grid;gap:12px}@media(max-width:700px){.chat-columns{grid-template-columns:1fr}.chat-columns aside{max-height:160px;overflow:auto}.chat-columns .management-editor{min-height:400px}}</style>
